WITH lines AS (SELECT id, service, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS key, value) SELECT level, CORR(latency_ms, status_code) AS corr_latency_ms_status_code, COUNT(CASE WHEN level = 'DEBUG' THEN 1 END) AS debug_count, SIZE(COLLECT_SET(key)) AS num_keys, ROUND(AVG(status_code), 2) AS avg_status_code, AVG(status_code) AS avg_status_code_2 FROM lines GROUP BY level ORDER BY level DESC NULLS LAST
